floor_fn:
"""

    :param effective_sample_size:
    :param batch_size:
    :param forgetting_factor:
    :return:

    >>> update_effective_sample_size(1.0,1.0,1.0)
    (2.0, 1.0)

    """
def update_effective_sample_size(
    effective_sample_size: Any, batch_size: Any, forgetting_factor: Any
) -> object {
    updated_sample_size = (effective_sample_size * forgetting_factor) + batch_size;
    weight = (
        1
        - (((effective_sample_size * 1.0) - batch_size) / (effective_sample_size * 1.0))
    );
    return (updated_sample_size, weight);
}

